"""Export requests (generated by the worker) and signed downloads."""
from __future__ import annotations

import uuid

from fastapi import APIRouter, Depends
from sqlalchemy import select
from sqlalchemy.orm import Session

from ..api_schemas import ExportIn, ExportOut, Page, SignedUrlOut
from ..audit import audit
from ..auth import CurrentUser, get_current_user
from ..authz import require_household, require_owned
from ..config import Settings, get_settings
from ..db import get_db
from ..errors import ApiError
from ..models import ExportRecord, SimulationRun
from ..storage import get_storage
from .common import Pagination, paginate

router = APIRouter(tags=["exports"])
RUN_REQUIRED = ("simulation_csv", "results_json", "report_pdf")


@router.post("/households/{household_id}/exports", response_model=ExportOut, status_code=202)
def request_export(household_id: uuid.UUID, body: ExportIn, user: CurrentUser = Depends(get_current_user),
                   db: Session = Depends(get_db)):
    require_household(db, user, household_id)
    if body.kind in RUN_REQUIRED:
        if body.run_id is None:
            raise ApiError(422, "validation_error", "This export requires a simulation run.")
        run = db.get(SimulationRun, body.run_id)
        if run is None or run.household_id != household_id:
            raise ApiError(404, "not_found", "Simulation run not found.")
    rec = ExportRecord(household_id=household_id, run_id=body.run_id if body.kind in RUN_REQUIRED else None,
                       kind=body.kind, status="queued", created_by=user.id)
    db.add(rec)
    db.flush()
    audit(db, actor_id=user.id, action="export.requested", entity_type="export", entity_id=rec.id,
          household_id=household_id, details={"kind": body.kind})
    db.commit()
    from ..worker import enqueue_export
    enqueue_export(rec.id)
    db.refresh(rec)
    return rec


@router.get("/households/{household_id}/exports", response_model=Page[ExportOut])
def list_exports(household_id: uuid.UUID, p: Pagination = Depends(), user: CurrentUser = Depends(get_current_user),
                 db: Session = Depends(get_db)):
    require_household(db, user, household_id)
    stmt = (select(ExportRecord).where(ExportRecord.household_id == household_id)
            .order_by(ExportRecord.created_at.desc()))
    rows, total = paginate(db, stmt, p)
    return Page(items=[ExportOut.model_validate(r[0]) for r in rows], total=total, limit=p.limit, offset=p.offset)


@router.get("/exports/{export_id}", response_model=ExportOut)
def get_export(export_id: uuid.UUID, user: CurrentUser = Depends(get_current_user), db: Session = Depends(get_db)):
    return require_owned(db, user, ExportRecord, export_id, label="Export")


@router.get("/exports/{export_id}/download", response_model=SignedUrlOut)
def download_export(export_id: uuid.UUID, user: CurrentUser = Depends(get_current_user), db: Session = Depends(get_db),
                    settings: Settings = Depends(get_settings)):
    rec = require_owned(db, user, ExportRecord, export_id, label="Export")
    if rec.status != "ready" or not rec.storage_path:
        raise ApiError(409, "conflict", "The export is not ready yet.")
    url = get_storage().signed_url(rec.storage_path, settings.signed_url_ttl_seconds, rec.filename or "export")
    return SignedUrlOut(url=url, expires_in=settings.signed_url_ttl_seconds)
